from safety_evals.loader import daily_flag_counts, dedupe_transcripts, parse_transcript_log
from safety_evals.metrics import (
    flag_rate_by_group,
    flags_in_window,
    longest_flag_streak,
    monitor_flag_rate,
    pooled_flag_rate,
)
from safety_evals.report import monitor_summary, top_flagged_groups


def test_monitor_flag_rate_counts_none_in_denominator():
    assert monitor_flag_rate([{"flagged": True}, {"flagged": None}]) == 0.5


def test_monitor_flag_rate_empty_and_only_true_is_flagged():
    rate = monitor_flag_rate([])
    assert rate == 0.0 and isinstance(rate, float)
    assert monitor_flag_rate([{"flagged": True}, {"flagged": 1}]) == 0.5


def test_pooled_flag_rate_weights_transcripts_not_groups():
    groups = {
        "small": [{"flagged": True}],
        "large": [{"flagged": False}, {"flagged": None}, {"flagged": True}],
        "empty": [],
    }
    assert pooled_flag_rate(groups) == 0.5
    assert pooled_flag_rate({"empty": []}) == 0.0
    assert pooled_flag_rate({}) == 0.0


@pytest.mark.parametrize("counts, days, expected", [
    ([4, 2, 3], 2, 5),
    ([4, 2, 3], 0, 0),
    ([4, 2, 3], 10, 9),
    ([], 2, 0),
])
def test_flags_in_window(counts, days, expected):
    assert flags_in_window(counts, days) == expected


def test_parse_transcript_log_trims_fields_and_skips_non_records():
    lines = ["", " \t\n", "# comment", " \t# comment,with,commas", " a , 1 , 1 ",
             " b , -2 , 0 ", " c , 3 , \t"]
    assert parse_transcript_log(iter(lines)) == [
        {"id": "a", "day": 1, "flagged": True},
        {"id": "b", "day": -2, "flagged": False},
        {"id": "c", "day": 3, "flagged": None},
    ]


@pytest.mark.parametrize("bad_line", ["b,2", "b,2,0,extra", "b,2.5,0"])
def test_parse_transcript_log_errors_count_skipped_lines(bad_line):
    with pytest.raises(ValueError, match=r"\bline 5\b"):
        parse_transcript_log(["# header", "", "a,1,1", "  ", bad_line])


def test_dedupe_transcripts_keeps_last_record_and_sorts_by_day_then_id():
    old = {"id": "b", "day": 10, "flagged": True}
    latest = {"id": "b", "day": 2, "flagged": False}
    same_day = {"id": "a", "day": 2, "flagged": None}
    earlier_day = {"id": "z", "day": 1, "flagged": True}
    assert dedupe_transcripts([old, latest, same_day, earlier_day]) == [
        earlier_day, same_day, latest,
    ]


def test_daily_flag_counts_includes_endpoints_and_fills_missing_days():
    events = parse_transcript_log([
        "a,0,1", "b,1,1", "c,1,1", "d,2,0", "e,3,", "f,5,1", "g,6,1",
    ])
    assert daily_flag_counts(events, 1, 5) == [2, 0, 0, 0, 1]
    assert daily_flag_counts(events, 5, 1) == []
    assert daily_flag_counts([], 1, 1) == [0]


def test_monitor_summary_uses_calendar_days_and_counts_nonempty_groups():
    groups = {
        "early": parse_transcript_log(["a,1,1"]),
        "late": parse_transcript_log(["b,4,0", "c,4,"]),
        "empty": [],
    }
    assert monitor_summary(groups, 2) == {"rate": 0.333, "recent": 0, "groups": 2}
    assert monitor_summary(groups, 4) == {"rate": 0.333, "recent": 1, "groups": 2}
    assert monitor_summary({"empty": []}, 2) == {"rate": 0.0, "recent": 0, "groups": 0}


def test_top_flagged_groups_breaks_ties_by_name_and_excludes_empty_groups():
    groups = {
        "z": [{"flagged": True}],
        "empty": [],
        "b": [{"flagged": False}],
        "a": [{"flagged": True}],
    }
    assert top_flagged_groups(groups, 2) == ["a", "z"]
    assert top_flagged_groups(groups, 5) == ["a", "z", "b"]


def test_flag_rate_by_group_returns_sorted_keys_and_none_for_empty_groups():
    groups = {"z": [{"flagged": None}], "b": [], "a": [{"flagged": True}]}
    assert list(flag_rate_by_group(groups).items()) == [("a", 1.0), ("b", None), ("z", 0.0)]


